#include <iostream>
#include <cstdint>
#include <string>
#include <bitset>
#include <iomanip>

int main() {
    // C.21: 1011110_2 to decimal
    std::string bin_str = "1011110";
    unsigned int val_from_bin = std::stoi(bin_str, nullptr, 2);

    // C.22: 426_8 to decimal
    std::string oct_str = "426";
    unsigned int val_from_oct = std::stoi(oct_str, nullptr, 8);

    // C.23: FFFF_16 to decimal
    std::string hex_str = "FFFF";
    unsigned int val_from_hex = std::stoi(hex_str, nullptr, 16);

    // C.24: Decimal 299 to bin, oct, hex
    unsigned int val_299 = 299;

    // C.26: 32-bit two's complement of -1
    int neg_one = -1;
    std::bitset<32> bs_neg_one(static_cast<std::uint32_t>(neg_one));

    std::cout << "bin 1011110 = " << val_from_bin << "\n";
    std::cout << "oct 426 = " << val_from_oct << "\n";
    std::cout << "hex FFFF = " << val_from_hex << "\n";
    std::cout << "299 in hex = " << std::hex << std::uppercase << val_299 << "\n";
    std::cout << "299 in oct = " << std::oct << val_299 << "\n";
    std::cout << "-1 in 32-bit hex = " << std::hex << bs_neg_one.to_ulong() << "\n";

    return 0;
}
